#[cfg(unix)]
#[test]
fn paging_with_plain_in_terminal() {
    for (args, pager_enabled) in [
        (vec!["--paging=never", "--plain"], false),
        (vec!["--plain", "--paging=never"], false),
        (vec!["--paging=never", "-p"], false),
        (vec!["-p", "--paging=never"], false),
        (vec!["--paging=always", "--plain"], true),
        (vec!["--plain", "--paging=always"], true),
        (vec!["--paging=always", "-pp"], false),
        (vec!["-pp", "--paging=always"], true),
        (vec!["--paging=auto", "-pp"], false),
        (vec!["-pp", "--paging=auto"], true),
        (vec!["--plain", "--paging=always", "--plain"], false),
        (vec!["-pp"], false),
        (vec!["--plain"], true),
    ] {
        let OpenptyResult { master, slave } = openpty(None, None).expect("Couldn't open pty.");
        let mut master = File::from(master);
        let output = bat_raw_command()
            .args(&args)
            .arg("--color=never")
            .arg("--pager=sh -c 'echo pager-output >&2; cat'")
            .arg("test.txt")
            .stdin(Stdio::null())
            .stdout(File::from(slave))
            .output()
            .expect("Failed to start.");

        output
            .assert()
            .success()
            .stderr(if pager_enabled { "pager-output\\n" } else { "" });

        let mut stdout = Vec::new();
        if let Err(error) = master.read_to_end(&mut stdout) {
            // Linux returns EIO when the slave end of a pty is closed.
            assert_eq!(error.raw_os_error(), Some(nix::libc::EIO), "{args:?}");
        }
        assert_eq!(stdout, b"hello world\\r\\n", "{args:?}");
    }
}

